Exercise 6:  
from random import randint 

def random_number(min = 1, max = 100): 
    return randint(min, max) 

rand_int = random_number() 

# print(rand_int) 
guess_num = int(input("Guess the number (1 <= x <= 100): " )) 
while rand_int != guess_num: 
    if rand_int > guess_num: 
        print("Your guess was to small" ) 
    else: 
        print( "Your guess was to big" ) 
    guess_num = int( input( "Guess the number: " ) ) 
print('Well guessed! The guess number was:{0:4d}' .format(guess_num)) 




